regions.text:
.grid-item {
 position: relative; 
 top: random(5rem, 20rem);
 right: random(5rem, 15rem);
}

/* Generate a random number from a set range of values */
.grid-items { 
 /* Result: Numeric value between 4rem-10rem, e.g. 8rem */
 top: random(4rem, 10rem);
}
/* Generate separate random numbers per element */
.grid-items {
 /* Result: Numeric value between 4rem-10rem for this instance */
 top: random(--per-element, 4rem, 10rem);
}
/* Generates random values in measured steps */
.grid-items {
 /

.grid-item {
 /* Generates 6rem or 11rem, etc. */
 font-size: random(1rem, 20rem, by 5rem);
 /* Generate 3.1rem, 4.2rem, or 5.3rem, etc. */
 padding: random(2rem, 10rem, by 1.1rem);
}

@for $i from 1 through 2 {
 .box:nth-child(#{$i}) {
 // random number between 1 and 5
 border: random(5) + px solid;
 // random number between 1 and 2 determines `dashed` or `dotted`
 border-style: nth((dashed, dotted), random(2));
 width: 2rem;
 height: 2rem;
 margin: 1rem 0;
 }
}

.element {
 top: random(4rem, 10rem);
}

.element-1 {
 /* Both result in the same random number */
 top: random(4rem, 10rem);
 left: random(4rem, 10rem);
}
.element-2 {
 /* Result in the same random number as .element-1 */
 top: random(4rem, 10rem);
}

/* DOES NOT WORK! */
.element {
 /* Choose one from the list: */
 top: random(4rem, 10rem, 16rem, 45rem);
}

/* CAUTION: Hypothetical example */
/* Choose one from the list: */
color: random-item(--x, red, blue, green);

But what if we’re using the by argument?
/* Generate a value in increments of 30px */
top: random(100px, 200px, by 30px);

/* Generate a value in increments of 30px */
/* Possible values: 100px, 130px, 160px, 190px */
top: random(100px, 200px, by 30px);

So, in essence:
.card { 
 /* Valid */
 padding: random(10rem, 20rem, by 5rem); 
 /* Invalid */
 padding: random(10rem, 5em, by 5px);
}

